const items = $input.all();

if (!items || items.length === 0) {
  return [{ json: { found: false } }];
}

const d = items[0].json;

// Simplify 模式關閉後用 properties，開啟後直接讀 key
// 先偵測是哪種結構
let props = d.properties;
let useProps = !!props;

const getString = (prop) => {
  if (!prop) return '';
  if (prop.type === 'title')      return (prop.title     || []).map(t => t.plain_text).join('');
  if (prop.type === 'rich_text')  return (prop.rich_text || []).map(t => t.plain_text).join('');
  if (prop.type === 'select')     return prop.select?.name || '';
  if (prop.type === 'checkbox')   return prop.checkbox || false;
  if (prop.type === 'created_time')     return prop.created_time || '';
  if (prop.type === 'last_edited_time') return prop.last_edited_time || '';
  return '';
};

const getImages = (prop) => {
  if (!prop || prop.type !== 'files') return [];
  return (prop.files || []).map(f => f.file?.url || f.external?.url || '').filter(Boolean);
};

let result;

if (useProps) {
  // Simplify OFF：完整 properties 結構
  const isPublic = getString(props['是否公開']);
  if (isPublic === false) return [{ json: { found: false } }];
  result = {
    found:        true,
    caseId:       getString(props['案件編號']),
    title:        getString(props['案件標題']),
    caseType:     getString(props['案件類型']),
    caseArea:     getString(props['案件區域']),
    status:       getString(props['案件狀態']),
    summary:      getString(props['公開摘要']),
    reply:        getString(props['回覆內容']),
    beforeImages: getImages(props['改善前圖片']),
    afterImages:  getImages(props['改善後圖片']),
    date:         getString(props['建立時間']).slice(0, 10),
    lastUpdate:   getString(props['上次編輯時間']).slice(0, 10)
  };
} else {
  // Simplify ON：直接讀 key
  if (!d['是否公開']) return [{ json: { found: false } }];
  const getImgSimple = (val) => {
    if (!val) return [];
    if (Array.isArray(val)) return val.map(f => f.url || f.file?.url || '').filter(Boolean);
    return [];
  };
  result = {
    found:        true,
    caseId:       d['案件編號']  || '',
    title:        d['案件標題']  || d.name || '',
    caseType:     d['案件類型']  || '',
    caseArea:     d['案件區域']  || '',
    status:       d['案件狀態']  || '',
    summary:      d['公開摘要']  || '',
    reply:        d['回覆內容']  || '',
    beforeImages: getImgSimple(d['改善前圖片']),
    afterImages:  getImgSimple(d['改善後圖片']),
    date:         (d['建立時間']     || '').slice(0, 10),
    lastUpdate:   (d['上次編輯時間'] || '').slice(0, 10)
  };
}

return [{ json: result }];
